package com.akitaattribute.mobfarmblock.block;
import com.akitaattribute.mobfarmblock.mob.StoredMob; import com.akitaattribute.mobfarmblock.registry.ModBlocks; import net.minecraft.block.BlockState; import net.minecraft.block.entity.BlockEntity; import net.minecraft.nbt.NbtCompound; import net.minecraft.network.listener.ClientPlayPacketListener; import net.minecraft.network.packet.Packet; import net.minecraft.network.packet.s2c.play.BlockEntityUpdateS2CPacket; import net.minecraft.registry.RegistryWrapper; import net.minecraft.util.math.BlockPos;
/** Stores only abstract mob profile data and absolute ready-at timestamps; no live entity NBT or simulation is persisted. */
public class MobFarmBlockEntity extends BlockEntity { private StoredMob stored=StoredMob.empty(); public MobFarmBlockEntity(BlockPos pos, BlockState state){super(ModBlocks.MOB_FARM_BLOCK_ENTITY,pos,state);} public StoredMob getStored(){return stored;} public void setStored(StoredMob s){stored=s; markDirty(); if(world!=null) world.updateListeners(pos,getCachedState(),getCachedState(),3);} @Override protected void writeNbt(NbtCompound n, RegistryWrapper.WrapperLookup l){super.writeNbt(n,l); n.put("storedMob",stored.toNbt());} @Override protected void readNbt(NbtCompound n, RegistryWrapper.WrapperLookup l){super.readNbt(n,l); stored=n.contains("storedMob")?StoredMob.fromNbt(n.getCompound("storedMob")):StoredMob.empty();} @Override public NbtCompound toInitialChunkDataNbt(RegistryWrapper.WrapperLookup l){var n=new NbtCompound(); writeNbt(n,l); return n;} @Override public Packet<ClientPlayPacketListener> toUpdatePacket(){return BlockEntityUpdateS2CPacket.create(this);} }
